<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue'; import { api } from '../services/api'; import { socket } from '../services/socket'; import type { PartyEvent } from '../types';
const events=ref<PartyEvent[]>([]); const error=ref(''); const form=reactive({title:'',description:'',maxPlayers:'',eventType:'CUSTOM'});
async function refresh(){events.value=await api.getEvents();}
async function create(){error.value='';try{await api.createEvent({title:form.title,description:form.description,maxPlayers:form.maxPlayers?Number(form.maxPlayers):null,eventType:form.eventType});form.title='';form.description='';form.maxPlayers='';form.eventType='CUSTOM';await refresh();}catch(e:any){error.value=e.message;}}
async function change(id:number,action:'start'|'complete'){try{await api.updateEvent(id,action);await refresh();}catch(e:any){error.value=e.message;}}
onMounted(()=>{refresh();socket.on('events:changed',refresh)});onUnmounted(()=>socket.off('events:changed',refresh));
</script>
<template><main class="page-shell admin-shell"><header class="topbar"><a class="brand" href="/">PARTY<span>CASINO</span></a><nav><a href="/">Játékos oldal</a><a href="/display" target="_blank">TV kijelző ↗</a></nav></header><section class="hero compact"><p class="eyebrow">VEZÉRLŐPULT</p><h1>Események <span>kezelése.</span></h1><p class="muted">Hozz létre eseményt, majd jelenítsd meg a TV kijelzőn.</p></section><section class="admin-layout"><form class="panel create-panel" @submit.prevent="create"><p class="eyebrow">ÚJ ESEMÉNY</p><h2>Esemény meghirdetése</h2><label>Esemény típusa<select v-model="form.eventType"><option value="CUSTOM">Általános esemény</option><option value="ROULETTE">Közös rulett</option></select></label><label>Esemény neve<input v-model="form.title" maxlength="60" required placeholder="Pl. Kvíz bajnokság"></label><label>Leírás<textarea v-model="form.description" maxlength="300" rows="3" placeholder="Rövid leírás és szabályok..."></textarea></label><label>Maximális létszám <span class="muted inline-hint">(üres = korlátlan)</span><input v-model="form.maxPlayers" type="number" min="1" max="100" placeholder="Pl. 12"></label><p v-if="error" class="error">{{ error }}</p><button class="primary full" :disabled="!form.title.trim()">Esemény létrehozása <span>→</span></button></form><section class="admin-events"><div class="section-heading"><div><p class="eyebrow">ESEMÉNYLISTA</p><h2>Meghirdetett események</h2></div><button class="ghost" @click="refresh">↻</button></div><article v-for="event in events" :key="event.id" class="panel admin-event"><div><span class="status" :class="event.status.toLowerCase()">{{ event.status }}</span><h3>{{ event.title }}</h3><p class="muted small">{{ event.participantCount }} résztvevő · {{ event.description }}</p><p class="participant-list">{{ event.participants.map(p=>p.name).join(', ') }}</p></div><div class="admin-actions"><button v-if="event.status==='OPEN'" class="primary" @click="change(event.id,'start')">Indítás</button><button v-if="event.eventType==='ROULETTE' && event.status==='RUNNING'" class="ghost" @click="api.spinRoulette(event.id).then(refresh).catch(e=>error=e.message)">Pörgetés</button><button v-if="event.eventType==='ROULETTE' && event.status==='RUNNING'" class="ghost" @click="api.nextRouletteRound(event.id).then(refresh).catch(e=>error=e.message)">Új kör</button><button v-if="event.status!=='COMPLETED'" class="ghost" @click="change(event.id,'complete')">Lezárás</button></div></article><div v-if="!events.length" class="empty panel"><p class="muted">Még nincs esemény.</p></div></section></section></main></template>
